-- GENERATED by `wfj generate` from data/quest/quest-0091.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [91208] = { "Fare i conti con la realtà", "Trova il Frightened Paladin ad ⟦Deathknell=Albamorta⟧.", "Non tutti i nostri confratelli paladini che risorgono si adattano in fretta alla nostra nuova realtà. Alcuni faticano ad accettare di essere ora, in un certo senso, proprio ciò che hanno combattuto per tutta la vita.\n\nSpesso a queste persone bastano un gesto gentile e un orecchio comprensivo. Purtroppo, molti altri diventano subito violenti. Trova la paladina spaventata fuggita sulle colline subito a ovest di questa cappella. Tendile una mano in amicizia. Riconducila alla Luce, se puoi.", nil, "Purtroppo non sono pochi i nostri fratelli e sorelle che cadono in una follia simile dopo essere risorti. Per quanto ogni anima dei Reietti sia preziosa, a volte il meglio che possiamo fare è concedere una fine pulita a chi non riesce ad adattarsi.\n\nDirò una preghiera alla Luce per lei. Grazie per aver fatto ciò che andava fatto, {name}.", 0x369056a8, 0x4e575d59, 0xf3aba797, nil, 0x08cfc7d1, "...m." },
  [91209] = { "Continua l'addestramento", "Segui la strada verso est fuori da ⟦Deathknell=Albamorta⟧ fino alla città di Brill. Fai rapporto a Shari Stilwell per continuare l'addestramento.", "Lordaeron non sarà più quella di un tempo, ma la nostra casa ha ancora bisogno di protezione da ogni genere di minaccia, ed è ora che tu esca ad affrontare il mondo. La tua prossima tappa è la città di Brill, nel cuore delle ⟦Tirisfal Glades=Radure di Tirisfal⟧. Va' a incontrare Shari Stilwell. Si occuperà del tuo addestramento.\n\nUn ultimo consiglio prima di partire: fa' molta attenzione, da paladin<o/a> in viaggio per le terre dei Reietti. Molti al servizio della Dama Oscura diffidano di noi e della nostra vicinanza alla Luce.", nil, "Benvenut<o/a> tra noi, {class}. È sempre incoraggiante vedere altri dei nostri percorrere queste terre. Qui a Brill in molti hanno bisogno dell'aiuto di avventurieri come te. Cerca lavoro e diventa più forte nella Luce. Torna da me ogni volta che ti serve addestramento.\n\nQuando avrai dato prova di te a me e alla gente di Brill, ti darò indicazioni per la prossima tappa del tuo viaggio.\n\nVa' con la Luce, {class}.", 0x4085cde1, 0x85d93d6b, 0xaa599bfa, nil, 0x5e8d646c, "...m." },
  [91282] = { "Una seconda casa", "Trova la fortezza di ⟦Bandarion Keep=Forte Bandarion⟧ e fai rapporto a Breton Samuels.", "È incoraggiante vedere i miei fratelli e sorelle appena risorti prosperare come hai fatto tu. Ma è solo attraverso la comunità e la fede condivisa che possiamo davvero realizzare il nostro pieno potenziale, ed è per questo che abbiamo iniziato a fondare un nuovo ordine di paladini proprio qui a Tirisfal.\n\nSe vuoi saperne di più, visita il nostro monastero ai margini dei Whispering Woods. Si chiama ⟦Bandarion Keep=Forte Bandarion⟧. Si trova sulle alture appena a nord-ovest della ⟦Solliden Farmstead=Cascina dei Solliden⟧: difficile non vederlo.", nil, "Un'altra recluta? Benvenuto a ⟦Bandarion Keep=Forte Bandarion⟧, fratello.", 0x323b0ccf, 0x66582164, 0x5716314a, nil, 0xeedd56bd, "...m." },
  [91285] = { "Murloc alle porte", "Uccidi $N1 Vile Fin Attacker e $N2 Vile Fin Seer, poi torna a riferire a Breton Samuels.", "Di solito saremmo più ospitali con i nuovi arrivati, ma al momento abbiamo un piccolo problema di murloc.\n\nUna tribù di murloc usava la fortezza per deporre le uova. Ci danno problemi da quando ci siamo trasferiti qui e li abbiamo cacciati, ma ora la situazione sta sfuggendo di mano. Sembri <uno/una> che ha visto un po' d'azione. Pensi di poterci aiutare a respingere qualcuno di questi parassiti? Li troverai appostati sulle alture lungo la strada a est e negli accampamenti intorno al lago a ovest.", nil, "Grazie dell'aiuto. Non credo che questo fermerà del tutto gli attacchi, ma spero che li rallenti un po'. È già abbastanza difficile ricostruire questo posto senza un murloc che cerca di piantarti una lancia nella schiena.", 0x7785ffc2, 0x7b21c67e, 0x12268215, nil, 0x273fdfba, "...m." },
  [91294] = { "Un giro della fortezza", "Parla con gli abitanti di ⟦Bandarion Keep=Forte Bandarion⟧.", "Ora che la minaccia immediata degli attacchi dei murloc è sotto controllo, ti consiglio di fare un giro della nostra roccaforte. Per ora non è granché, ma è casa nostra.\n\nQuando avrai finito di esplorare, cerca Danitha Morr, la nostra comandante. Ti aiuterà a sistemarti.\n\nSono davvero lieto di averti conosciuto, {name}. Che la Luce ti guidi.", nil, "Ti ha mandato Breton, eh? Ottimo.\n\nMi chiamo Danitha Morr, e sono quanto di più vicino a un comandante abbia questa fortezza. Se cerchi fratellanza tra coloro che restano ancora fedeli alla Luce, sei nel posto giusto.\n\nC'è molto lavoro da fare qui prima di poterci stabilire del tutto, e ti saremmo molto grati se volessi darci una mano.", 0x2887ca72, 0x410e846c, 0x44585301, nil, 0x902d5c25, "...m." },
  [91316] = { "Riparazioni", "Raccogli 12 ⟦Sturdy Lumber=Legname Robusto⟧ a ⟦Shadowvale=Valle Ombrosa⟧, nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Così lontano da ⟦Undercity=Sepulcra⟧, i rifornimenti sono un problema e abbiamo una grave carenza dei materiali da costruzione che servono a restaurare questa fortezza. Vorrei il tuo aiuto.\n\nIl villaggio in rovina di ⟦Shadowvale=Valle Ombrosa⟧ si trova nella ⟦Whispering Forest=Foresta Sussurrante⟧, appena a sud-ovest di qui. In uno degli edifici c'è una vecchia cantina usata per conservare ogni sorta di cose. Probabilmente laggiù ci sono materiali utilizzabili. Recupera ciò che puoi e torna da noi.", "Si dice che la posizione sia tutto. Questa fortezza arroccata su queste alture avrà anche un aspetto imponente, ma restare riforniti così lontano dalla civiltà vera e propria si sta rivelando una bella sfida. Una svista spiacevole da parte nostra.", "Mi fa piacere che il tuo viaggio a ⟦Shadowvale=Valle Ombrosa⟧ abbia dato i suoi frutti. Più tardi manderò Breton e qualche altra nuova recluta a svuotare il resto della cantina e a recuperare ciò che è rimasto laggiù, al buio.", 0x2cfcd9f0, 0xb8282c24, 0x1518690b, 0x7517517d, 0xdf7b4d57, "....." },
  [91317] = { "I Tarnished", "Uccidi 8 Tarnished Drudge e 6 Tarnished Zealot, e raccogli la testa di Commander Rudolph Gelhardt nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Non tutti i paladini risorti si sono adattati bene alla nostra nuova esistenza, come forse hai già visto con i tuoi occhi. Alcuni si sono portati dietro i pregiudizi della vita, e continuano a usare violenza contro i loro compagni Reietti.\n\nAllo stato attuale la nostra gente diffida di noi, perché ricorda bene le persecuzioni inflitte dai vivi in nome della Luce, e questi attacchi non aiutano. Un certo numero di questi Tarnished si è stabilito a ⟦Shadowvale=Valle Ombrosa⟧, a sud-ovest. Eliminali e portami la testa del loro capo.", "I Tarnished minacciano quel poco di benevolenza che abbiamo presso gli altri Reietti. Per quanto mi addolori incrociare le lame con quelli che erano nostri fratelli e sorelle, vanno fermati se il nostro giovane ordine vuole sopravvivere.", "Ottimo lavoro, {name}. Ogni volta che uno di questi Tarnished colpisce e uccide uno dei Reietti, per i nostri detrattori diventa ancora più facile alimentare la diffidenza verso noi paladini. Eliminarli aiuterà la nostra causa e consoliderà il nostro posto qui a Tirisfal.\n\nSospetto che ci vorrà molto tempo prima che i Reietti e l'Orda ci accolgano davvero. Potrebbero volerci anni... o forse decenni, ma il meglio che possiamo fare è continuare a dimostrare il nostro valore.", 0x56e9442f, 0x783dab34, 0x72df7fd8, 0x41fb5732, 0x6fd3aac2, "....." },
  [91488] = { "Casa tra i pascoli", "Porta 5 Pelle di Zoccolomuschio a Kurll a Valormok, ad Azshara.", "Durante il nostro ultimo scontro con gli elfi del sangue, la mia tenda è stata gravemente danneggiata. Per tre notti ho dovuto restare in balia degli elementi.\n\nPuò essere riparata con qualche Pelle di Zoccolomuschio, ma la mancanza di sonno mi ha reso incapace di cacciarli io stesso.\n\nGli zoccolomuschio più facili da cacciare sono a ovest e a sud di qui, ma va bene la pelle di qualsiasi zoccolomuschio.", nil, nil, 0x92b07f24, 0x2ffe583f, 0x1fdd6890, nil, nil, "...mm" },
  [91497] = { "Sigilli dei Sin'dorei", "Porta il Sigillo del Custode, il Sigillo del Guerriero e il Sigillo del Ranger al Tomo dell'Evocazione Sin'dorei.", "<Il sigillo del primo cristallo reca il marchio di una spada. La sua energia deve essere incanalata da un guerriero esperto.\n\nIl sigillo del cristallo centrale reca il marchio di un glaive. La sua energia deve essere incanalata da chi possiede sia abilità marziale sia magica.\n\nIl sigillo dell'ultimo cristallo reca il marchio di un artiglio. La sua energia deve essere incanalata da chi si sente a casa nella natura selvaggia.\n\nÈ probabile che alcuni ufficiali di Rimtori portino questi sigilli per aiutarla nell'incantesimo. Portarglieli via le creerebbe di certo dei problemi.>", nil, nil, 0x10a86abd, 0xe995c95f, 0x08dcc1f2, nil, nil, "...mm" },
  [91500] = { "Un azzardo esplosivo", "Spezza i Sigilli dei Sin'dorei, poi porta la testa della Magus Rimtori a ⟦Ag'tor Bloodfist=Ag'tor Pugnorosso⟧ a Valormok.", "<Visto come le energie dei cristalli sono sintonizzate con i sigilli, deduci che distruggere un sigillo, liberandone tutta l'energia in una volta, potrebbe far fare lo stesso al suo cristallo.\n\nI risultati esplosivi attirerebbero senza dubbio l'ira di Rimtori. Offrirebbero anche l'occasione perfetta per attaccarla mentre è sconvolta.>", nil, nil, 0x5296f2ae, 0x545efb65, 0x808ab8bc, nil, nil, "...mm" },
  [91531] = { "Vendetta compiuta", "Porta la ⟦Head of Magus Rimtori=Testa della Magus Rimtori⟧ a ⟦Belgrom Rockmaul=Belgrom Mazzaroccia⟧ a Orgrimmar.", "Torna da Belgrom a Orgrimmar. Vorrà vedere la sua testa con i propri occhi!\n\nAh, questo è davvero un bel giorno. Grazie per il tuo aiuto, {name}.", nil, nil, 0xe8fde394, 0x5f06260a, 0xf9976772, nil, nil, "...mm" },
  [91538] = { "Tomo dell'Evocazione Sin'dorei", "Riporta il Tomo dell'Evocazione Sin'dorei a Jediga a Valormok.", "Il tomo di Rimtori si trova ancora sul suo piedistallo. Chissà quali segreti potrebbero custodire le sue pagine?\n\nForse sarebbe meglio non lasciare un artefatto così potente qui, in mezzo alla natura selvaggia.", nil, nil, 0x48bef3b2, 0xa12970e0, 0x528f3398, nil, nil, "...mm" },
  [91547] = { "Tomo dell'Evocazione Sin'dorei", "Porta il Tomo dell'Evocazione Sin'dorei a Zevrost a Orgrimmar.", "Hai fatto bene a prenderlo, {name}. Più che uccidere Rimtori, tenere questo lontano dalle mani degli elfi del sangue garantirà che non possano reagire contro di noi.\n\nQuanto a decifrare il tomo stesso, ho un contatto a Orgrimmar che si diletta in queste cose: uno stregone di nome Zevrost. Lo trovi nella Faglia dell'Ombra.", nil, nil, 0x48bef3b2, 0xd10da640, 0x38e99ec6, nil, nil, "...mm" },
  [91548] = { nil, "Usa il Tomo dell'Evocazione Sin'dorei per evocare Vek'zol all'⟦Altar of Storms=Altare delle Tempeste⟧ nelle ⟦Blasted Lands=Terre Devastate⟧. Porta il Cuore di Vek'zol a Zevrost a Orgrimmar.", "Non parlo thalassiano, ma questi diagrammi mi sono familiari.\n\nConoscendo la dipendenza degli elfi del sangue dal mana, direi che stavano cercando di evocare demoni per prosciugarli della loro magia vile.\n\nConsumare semplicemente un'energia così potente è uno spreco. Potremmo sfruttarla per uno scopo molto più grande.\n\n<Zevrost segna una pagina del tomo>\n\nNelle ⟦Blasted Lands=Terre Devastate⟧ c'è un ⟦Altar of Storms=Altare delle Tempeste⟧. Esegui lì questo rituale per evocare il demone Vek'zol. Il suo cuore sarà un potente reagente. Pensa al potere che potremmo avere!", nil, nil, 0x4acf1b9b, 0xfac65d21, 0x4e34ab78, nil, nil, "e..mm" },
  [91564] = { "Voglia di aggiustare", "Porta $N1 Rivestimento di Mithril e $N2 ⟦Mechanical Repair Kit=Kit per Riparazioni Meccaniche⟧ a Hnaz Fiammacurva.", "Siamo bloccati qui da cinque anni e abbiamo dovuto costruire tutto da zero! Sai quanto ho dovuto improvvisare solo per fare un po' di ingegneria?\n\nEhi, se puoi aiutarmi con qualche materiale, posso renderti il favore! Costruiscimi un paio di Rivestimenti di Mithril e un ⟦Mechanical Repair Kit=Kit per Riparazioni Meccaniche⟧ così potrò sistemare un po' di cose, e ti mostrerò alcune cose che ho scoperto.", nil, nil, 0xc2de022c, 0x88eedc84, 0x55c696ec, nil, nil, "...mm" },
  [91568] = { "Lunghe passeggiate sulla spiaggia", "Scava $N1 Frammento di Tesoro degli ⟦Highborne=Alti Nobili⟧ con la Paletta Cercatesori 3000 per Izvi Frizzadoro a Valormok.", "Quello che alle spiagge di qui manca in bellezza, lo compensano in valore!\n\nLa maggior parte delle rovine qui è stata ripulita, ma sotto quella sabbia c'è del bottino serio. Il problema è che è tutto sparpagliato, e con i naga una lunga ricerca è poco pratica. Quindi, cosa può fare una ragazza?\n\nEcco a te la Paletta Cercatesori 3000! La pala tuttofare che individua i tesori! Una mia invenzione personale.\n\nPorta questa bellezza sulla riva orientale e riportami tutto quello che trovi. Poi ci dividiamo i profitti!", nil, nil, 0x838bf4d8, 0x53501b21, 0x91d0fc20, nil, nil, "...mm" },
  [91569] = { "Oro blu", "Porta una Bacchetta Succhiamana a Izvi Frizzadoro a Valormok.", "Ascolta, <ragazzo/ragazza>, qui fuori tutti si affannano per la stessa cosa. Belgrom, gli elfi, i naga, tutti vogliono un pezzo di quell'antica magia degli Alti Nobili.\n\nIo? Non me ne importa niente, ma riconosco un mercato dei venditori quando ne vedo uno.\n\nHo visto degli arcanisti elfi del sangue con delle speciali bacchette. Servono a estrarre energia magica dagli artefatti che gli elfi trovano. Gli arcanisti stanno in un accampamento a est del campo base degli elfi, lungo le scogliere. Portami una di quelle bacchette e ti metterò sulle tracce del colpo della vita!", nil, nil, 0x73be6102, 0x6dd39b7c, 0xbf753062, nil, nil, "...mm" },
  [91607] = { "Filone fortunato!", "Trova qualcuno che possa valutare il Cristallo Enorme.", "<Il grosso pezzo di cristallo è ancora più pesante di quanto sembri. Pur sembrando un bel premio, la sua vera natura ti è ignota. Qualcuno con occhio per gli oggetti di valore potrebbe dirti cosa hai davvero trovato.>", nil, nil, 0x89afa7ee, 0x45a72cf5, 0xc8043f3d, nil, nil, "...mm" },
  [91608] = { "Un bel ronzio", "Raccogli $N1 Miele Selvatico da un Nido di Vespe usando il Fucile a Pallini di Kurll.", "Qui sulla frontiera ci sono pochi lussi. Un barile di una buona bevanda darebbe di certo una spinta al morale dell'accampamento.\n\nNei miei anni più giovani ho preso la ricetta di una deliziosa bevanda dal cadavere di un nano che avevo ucciso. Mi serve solo del miele. Per fortuna, i nidi di vespe a ovest ne sono pieni.\n\nPrendi il mio fucile a pallini. Ti permetterà di far cadere i nidi dagli alberi. Attenzione però: farà ben poco contro le vespe stesse.", nil, nil, 0x1c810d6b, 0xd286b8d9, 0xebd99998, nil, nil, "...mm" },
  [91610] = { "Pescheria della frontiera invernale", "Pesca 10 Calamaro Invernale per Kurll a Valormok.", "La carne va bene, ma una dieta varia rende il corpo più forte.\n\nI calamari invernali sono di stagione e si possono pescare dalle coste qui ad Azshara. La pesca non fa per me. Preferisco di gran lunga la sicurezza della terraferma. Tuttavia, se ne pescassi qualcuno, o te li procurassi in altro modo, ti sarei molto grato.", nil, nil, 0x3c26918f, 0x552864f4, 0x17011cc4, nil, nil, "...mm" },
  [91611] = { "Pesca mortale", "Porta una Bistecca di ⟦Mammoth Shark=Squalo Mammut⟧ a Kurll a Valormok.", "Se desideri una vera prova di abilità nella pesca, ci sono pesci più grossi di quelli che si prendono con una canna.\n\nGli squali mammut si nascondono nelle acque più profonde delle coste settentrionale e meridionale. Nuotano lontano, proprio dove il fondale precipita nel grande oceano.\n\nSono creature enormi. Ti consiglio di portare con te un gruppo di caccia.\n\nSe ne cacci uno, portami un trancio di carne.", nil, nil, 0xb3dfd878, 0xdca268b5, 0x662f0a7a, nil, nil, "...mm" },
  [91685] = { "Linee di potere del territorio", "Usa la Bacchetta Succhiamana sullo Squarcio della Linea di Potere nel ⟦Lake Mennar=Lago Mennar⟧ e porta la Lacrima di Mennar a Izvi Frizzadoro.", "Quando siamo arrivati qui, ho fatto un po' di prospezioni per trovare risorse inesplorate. Sai, roba tipica da prospettore.\n\nNon ho visto niente di speciale finché non ho esplorato il ⟦Lake Mennar=Lago Mennar⟧, a sud. Lì ho visto una grossa faglia fluttuare sopra la superficie dell'acqua. Non sono riuscito ad avvicinarmi, ma credo fosse una linea di potere aperta.\n\nSe ho ragione, possiamo usare questa bacchetta per succhiare magia direttamente dalla fonte! La imbottigliamo, la vendiamo al miglior offerente e bam! Sono ricco!\n\nSe vai a prosciugare quella faglia per me, ti faccio entrare nell'affare.", nil, nil, 0xcfc5068d, 0xd023d180, 0xdb0d4f01, nil, nil, "...mm" },
  [91688] = { "Alla Vetta dell'Eternità", "Recati alla Vetta dell'Eternità e parla con i druidi del villaggio dei sopravvissuti.", "Sei riuscit<o/a> ad aprirti un varco tra i non morti che ci hanno tenuti intrappolati qui per così tanti anni, e per questo non potremo mai ripagarti.\n\nHo un ultimo favore da chiederti, a nome di tutti noi. Sappiamo che sulla vetta ci sono dei druidi. Proteggono Nordrassil e il ⟦Well of Eternity=Pozzo dell'Eternità⟧.\n\nPerché non sono mai venuti ad aiutarci a fuggire?\n\nSono cinque anni che siamo intrappolati qui. Finalmente abbiamo un barlume di speranza... ma perché i druidi non sono venuti a prenderci?\n\nFai sapere a qualcuno che siamo ancora vivi!", nil, nil, 0xb966c23b, 0xc3763a22, 0x8789a3c9, nil, nil, "...mm" },
  [91696] = { "Caccia aperta", "Scorta la Matriarca dei Pelledura fuori dalla Tana Legnomorto e torna alla Tana dei Pelledura.", "I Legnomorto si sono avventati sul mio cucciolo e su suo padre. Lui ha resistito, ha combattuto fino alla morte a nostra difesa. Dobbiamo tornare a casa, ma la strada è buia e piena di fauci.\n\nRestaci vicino, proteggici bene. Io guido, tu respingi, e vedremo la tana al sicuro.", nil, nil, 0xa149de2b, 0xa81a4108, 0x76f64f43, nil, nil, "...mm" },
  [91697] = { "Incontro con gli anziani", "Trova e parla con l'Anziano Zampanebbia e l'Anziano Parlapino nella Tana dei Pelledura.", "Grazie per aver aiutato a raccogliere le bacche d'orso. Piccoli passi costruiscono la fiducia! Con l'aroma della resina di bacche addosso, gli Anziani dovrebbero accoglierti meglio.\n\nVai a parlare con l'anziano Zampanebbia e l'anziano Parlapino.", nil, nil, 0x64d9279d, 0x9d9327c5, 0xe6dd8382, nil, nil, "...mm" },
  [91698] = { "Evasione dei Pelledura", "Recupera una Chiave dei Legnomorto da un Guardiano Legnomorto e torna alla Gabbia dei Pelledura.", "<Una mezzorsa matriarca ti parla da dentro la gabbia>\n\n\"I Legnomorto intrappolano me e mio cucciolo in gabbia dura. Chiave appesa a cintura di Guardiano Legnomorto. Tu cacciare loro, prendere chiave, alzare chiavistello, liberare noi. Fai questo, e Pelledura sa che tuo cuore vero.\"", nil, nil, 0xe2569cb7, 0x4e85f299, 0xf9c4c406, nil, nil, "...mm" },
  [91723] = { "Strumenti delicati", "Uccidi 8 Kobold Geomancer nella ⟦Jasperlode Mine=Miniera Venarossa⟧, poi torna da Hamish Bergwort nella ⟦Tower of Azora=Torre di Azora⟧.", "Accidenti! Ogni volta che provo a calibrare questi delicati strumenti arcani, un'ondata di energia li sballa di nuovo.\nLe ondate sembrano arrivare da nord, dove quei coboldi primitivi praticano la loro rozza magia. Potresti eliminarne qualcuno, così posso continuare il mio lavoro?", "Fammi sapere quando hai finito, così posso provare a calibrare di nuovo i miei strumenti.", "Ben fatto, amico mio. Fammi riprovare con le calibrazioni...", 0x7065a8eb, 0xe5f80ea7, 0x91c5f081, 0x5422bfc3, 0x8dec828f, "....." },
  [91724] = { "Strumenti delicati", "Uccidi $N1 Defias Rogue Wizard presso il ⟦Stone Cairn Lake=Lago del Memoriale⟧, poi torna da Hamish Bergwort nella ⟦Tower of Azora=Torre di Azora⟧.", "Ci siamo quasi, e... per il Nether! Qualcosa disturba ancora i miei strumenti.\n\nÈ davvero frustrante, {name}. Ho sentito dire che i banditi della zona si esercitano con gli incantesimi vicino al ⟦Stone Cairn Lake=Lago del Memoriale⟧. Forse, se li fermi, queste interferenze cesseranno finalmente e potrò combinare qualcosa?", nil, "Sembra che tutto funzioni come si deve. Grazie, {name}.", 0x7065a8eb, 0xbccc5d13, 0xe7761ff1, nil, 0x4af97dcf, "...m." },
  [91725] = { "Materiali d'incantamento rubati", "Raccogli 5 ⟦Stolen Enchanting Supplies=Materiali per Incantamento Rubati⟧ negli accampamenti degli gnoll intorno al ⟦Stone Cairn Lake=Lago del Memoriale⟧, poi torna da Blixie Fitzwink vicino alla ⟦Tower of Azora=Torre di Azora⟧.", "Mi ha mandato il maestro Theocritus a prendere dei materiali d'incantamento all'emporio, ma sulla via del ritorno un branco di gnoll mi ha teso un'imboscata!\n\nHo lasciato cadere il pacco e me la sono data a gambe, ma se torno senza, per punizione passerò settimane a ripulire dopo gli esperimenti di metamorfosi! Pensi di poter ritrovare i materiali per me?", "Hai trovato i materiali?", "Oh, che sollievo! Sembra che ci sia tutto. Grazie!", 0x78bd98c1, 0xeda8b676, 0xd9d3fe8f, 0x3a2cb041, 0x3db19b3c, "....." },
  [91732] = { "Buon acciaio", "Raccogli 4 ⟦Mining Tools=Attrezzi da Estrazione⟧ nella ⟦Jasperlode Mine=Miniera Venarossa⟧, poi torna da Hagar Lowe al ⟦Eastvale Logging Camp=Campo di Taglio di Vallevante⟧.", "Dopo la guerra il buon acciaio scarseggia, e i nostri attrezzi ne hanno risentito. I minatori della Miniera Venarossa usavano picconi di ottima fattura, e immagino che qualcuno sia ancora laggiù, nelle profondità della miniera. Potresti recuperarne alcuni per me? Vedrò se riesco a riutilizzarne l'acciaio.", "Sei già <stato/stata> alla miniera?", "Oh, molto bene. Vedi come brillano? Davvero, non li fanno più come una volta.", 0x72aed2a2, 0xd649abdf, 0x8701f873, 0xbc85eca8, 0x47745ccb, "....." },
  [91733] = { "Seguendo la corrente", "Recupera Waterlogged Axe, ⟦Waterlogged Saw=Sega Fradicia⟧ e ⟦Waterlogged Toolbox=Cassetta Fradicia⟧, trascinati dalla corrente a valle del ⟦Eastvale Logging Camp=Campo di Taglio di Vallevante⟧, poi torna da Ormin Pelford.", "Stavo riportando un carico di rifornimenti dall'emporio, ma il carro si è ribaltato e la roba è finita nel fiume! Prima che riuscissi ad afferrarla, la corrente l'aveva già trascinata a valle.\n\nCon i murloc e i lupi laggiù, per conto mio non ho nessuna speranza di recuperarla. Sembri una persona robusta. Pensi di poterla ritrovare per me?", "Hai trovato i materiali?", "Sei un po' <bagnato/bagnata>, {name}. Mi dispiace. Ma grazie per aver recuperato i materiali.", 0x5377b6c2, 0x4104ac2d, 0x5c21b1ba, 0x3a2cb041, 0xc2d835d9, "....." },
  [91734] = { "Contatto a distanza", "Parla con Jediga ad Azshara.", "<Il Reietto barcolla in modo instabile>\n\nEhi! <hic> Fammi un favore ... ti va?\n\nVai a uh ... Azshara e ... di' a <hic> Jediga ...\n\nChe aspetto una ... consegna ... importante <hic>", nil, nil, 0xd066ec07, 0x3ddb4b4d, 0x0e09b797, nil, nil, "...mm" },
  [91735] = { "Contatto a distanza", "Parla con Jediga ad Azshara.", "Ascolta, {class}, faresti meglio a non fermarti qui a lungo. Ma visto che ci sei, magari puoi farmi un piccolo favore?\n\nAspetto una certa cosa da una certa Jediga, ad Azshara. Lei e degli orchi hanno un accampamento là fuori. Vai a dirle che ti manda Jes'rimon, e ti sarò debitore.", nil, nil, 0xd066ec07, 0x3ddb4b4d, 0xdf413697, nil, nil, "...mm" },
  [91736] = { "L'alambicco dell'acquavite di mele", nil, nil, "Un forte odore di mele ti brucia il naso mentre esamini il congegno.", "La macchina eroga un liquido trasparente in una bottiglia...", 0xdf027785, nil, nil, 0x90ed44dc, 0x8ee6ab89, ".mm.." },
  [91737] = { "Contatto a distanza", "Parla con Jediga ad Azshara.", "I miei doveri richiedono a volte reagenti dai più remoti angoli di Azeroth. Tuttavia, qui a ⟦Thunder Bluff=Picco del Tuono⟧ ho sempre bisogno di me, e dunque ho bisogno di aiutanti competenti.\n\nA tal fine, attendo una consegna da un'orchessa di nome Jediga, ad Azshara. Se vuoi renderti utile, trova il suo accampamento e chiedile quando posso aspettarmela.", nil, nil, 0xd066ec07, 0x3ddb4b4d, 0x12eb924b, nil, nil, "...mm" },
  [91738] = { "Una delizia alla mela", nil, nil, "<Gli occhi del sergente si illuminano quando nota la tua bottiglia di Sidro del Tuono...>", "I miei occhi mi ingannano? Non vedo una goccia di Sidro del Tuono da mesi!\n\nQuesto dovrebbe far tornare il sorriso alle truppe. Hai la mia gratitudine, {class}!", 0xc00668c0, nil, nil, 0x751b6647, 0xd1ac4c89, ".mm.." },
  [91740] = { "La testa di Croaky", "Consegna la ⟦Croaky's Head=Testa di Croaky⟧ a Merell Ross alla ⟦Ridgepoint Tower=Torre Cresta Alta⟧.", "Senza dubbio questo murloc terrorizzava le strade della zona da tempo. Sospetti che le guardie di ronda nei dintorni vorranno sapere della sua fine.", "Sì?", "La settimana scorsa abbiamo perso due membri della guardia per colpa dei murloc, {class}. Speriamo che, ora che il loro capo è morto, potremo cominciare a ricacciarli fuori da Elwynn.", 0x9a2d8e95, 0xfefeb249, 0x70acafd1, 0x0c07a888, 0x8d54c4b8, "....." },
  [91741] = { "Un libro rosicchiato", "Restituisci il libro a fratello Paxton.", "<Uno dei coboldi ha lasciato cadere questo libro. Sembra che il coboldo abbia cercato di mangiarlo.\n\n⟦Brother Paxton=Fratello Paxton⟧, nell'abbazia, cura una piccola biblioteca. Il libro deve venire da lì.>", "Cos'hai lì? Sembra uno dei miei libri.", "Ehi! Come mai ce l'hai tu? Dovrebbe stare sullo scaffale! Oh cielo, i coboldi mi stanno di nuovo rubando i libri. Vorranno mangiarseli!\n\nGrazie per avermi riportato il libro, ma come farò con il resto della mia collezione scomparsa?", 0xdc36fd8f, 0x60fd6d4c, 0x926272a4, 0xb5ada1fe, 0xbe3f5ca7, "....." },
  [91743] = { "Roditori birbanti", "Recupera $N1 Stolen Book dai coboldi nella ⟦Northshire Valley=Valle della Contea del Nord⟧ e riportali a fratello Paxton.", "Quei terribili coboldi si mangiano i miei libri! Devi recuperarli prima che divorino tutta la mia biblioteca.", "Hai già salvato i miei libri, {name}?!", "Grazie mille! Ecco! Prendi uno di questi manuali pratici. A me non servono.\n\nMa mancano ancora tantissimi libri. Pare che i coboldi non li mangino. E allora perché li vogliono?", 0x5ecfe128, 0xca0dec56, 0x36c2ff3a, 0x9e3c12c9, 0xcb496646, "....." },
  [91745] = { "Consulenza mineraria", "Parla con Kelsey Fargo fuori dalla ⟦Echo Ridge Mine=Miniera Cresta dell'Eco⟧, nella ⟦Northshire Valley=Valle della Contea del Nord⟧.", "Va' a parlare con la nuova apprendista minatrice, Kelsey Fargo. Lavora proprio fuori dalla miniera e probabilmente ha visto cosa combinano i coboldi. Magari, già che ci sei, può insegnarti un paio di cose sull'Estrazione.", nil, "Coboldi con dei libri? Sì, ho visto coboldi correre avanti e indietro con dei libri, urlandosi addosso. Li staranno rubando dalla biblioteca dentro l'abbazia.", 0x70de9b61, 0x928069a0, 0x595703ec, nil, 0x968f291e, "...m." },
  [91746] = { "La testa di Elmpaw", "Consegna la ⟦Elmpaw's Head=Testa di Elmpaw⟧ a ⟦Helene Peltskinner=Helene Scuoiapelli⟧ vicino a ⟦Goldshire=Borgodoro⟧.", "Il trofeo è un ricordo impressionante della tua vittoria su Elmpaw. Un cacciatore o uno scuoiatore della zona potrebbe essere interessato a sentire la storia.", "Sì?", "Allora, hai abbattuto Elmpaw? Davvero notevole, {name}!\n\nLascia che ti dia qualcosa in cambio del tuo trofeo: conosco alcuni collezionisti che pagheranno parecchio per averlo sopra il camino, una volta che l'avrò preparato.", 0x6c96dddb, 0xa7c38435, 0x2ae37dbd, 0x0c07a888, 0xd51955d8, "....." },
  [91751] = { "Pelli di lupo grezze", "Scuoia i lupi nella ⟦Elwynn Forest=Foresta di Elwynn⟧ per ottenere $N1 Rough Wolf Pelt, poi consegnali a ⟦Helene Peltskinner=Helene Scuoiapelli⟧ vicino a ⟦Goldshire=Borgodoro⟧.", "Cerchi un'occasione per fare pratica di Scuoiatura? Di solito mio marito mi aiuta a cacciare i lupi, ma è impegnato su all'abbazia. Mi farebbe comodo una mano a raccogliere altre pelli per completare gli ordini a cui sto lavorando.", "Novità con quelle pelli di lupo?", "Ottimo lavoro con queste pelli, {class}. Hai un vero talento per la caccia.", 0xe1344efa, 0x35d88064, 0x993378eb, 0xc1490377, 0x024aeaa4, "....." },
  [91752] = { "Il quadro generale", "Recupera un sacco di libri \"illustrati\" da Shinyfinder Narf. Porta il sacco al maresciallo McBride, appena dentro l'Abbazia della Contea del Nord.", "Ogni tanto passa di qui un coboldo che urla \"Figure per Narf!\" Non so chi sia questo Narf. Forse uno dei capi coboldi in fondo alla miniera? Scommetto che ormai ha un sacco pieno di libri.\n\nVa' a prendere quei libri e portali al nostro tutore della legge, il maresciallo McBride. Faresti bene a trovare qualcuno che ti aiuti. I coboldi dentro la miniera sono molto più cattivi.", "Hai già recuperato quei libri rubati?", "Grazie per aver riportato questi libri rubati, {name}. Li restituirò subito a fratello Paxton.\n\nStai diventando <un/una> <vero/vera> <eroe/eroina> da queste parti. Ottimo lavoro!", 0xf0a9a4ae, 0x0274d4d1, 0x64d74190, 0x98bda539, 0x3c4f5b85, "....." },
  [91753] = { "Una lezione d'incantamento", "⟦Kitta Firewind=Kitta Bruciavento⟧, nella ⟦Tower of Azora=Torre di Azora⟧, vuole che tu raccolga 3 ⟦Luminous Residue=Residuo Luminoso⟧.\n\nPuoi ottenere il ⟦Luminous Residue=Residuo Luminoso⟧ disincantando le Crude Wax Effigy lasciate dai Kobold Geomancer.", "Il rigore accademico è certo essenziale nell'arte dell'incantatore, ma una base pratica può dare i suoi frutti. Considera, ad esempio, l'umile coboldo. Pur privo di un'istruzione formale, dimostra una sorta di attitudine innata per semplici trucchetti e incantamenti.\n\nProcurati alcune delle loro effigi di cera e scomponi gli incantamenti racchiusi al loro interno. Potrebbe rivelarsi illuminante.", "Che cosa hanno rivelato i tuoi studi?", "Teoria e pratica sono due facce della stessa medaglia, {name}. Ricordalo.", 0x775e64ad, 0x5706d360, 0x77774694, 0xcd72ab2a, 0x3bbdc1ae, "....." },
  [91754] = { "Un po' di terra sulla ferita", "Raccogli $N1 campioni di Terra Incontaminata sulle pendici del ⟦Mount Hyjal=Monte Hyjal⟧.", "Non vedevo nessuno come te, {race}, da anni!\n\nOh, non so cosa fare! Il mio amico Fraxinus è malato e non posso lasciarlo solo!\n\nPotresti portarmi un po' di Terra Incontaminata dalle terre non corrotte a sudest di qui? Posso preparare degli impiastri che potrebbero farlo sentire meglio.", nil, nil, 0x4c0632a9, 0xb8fe4764, 0x3f12aa32, nil, nil, "...mm" },
  [91755] = { "Dalle foglie alle bende", "Raccogli $N1 Foglie Verdeggianti da un Arbusto Contaminato sulle pendici del ⟦Mount Hyjal=Monte Hyjal⟧.", "Hai visto quegli orrendi arbusti contaminati che vagano per questa valle?\n\nQuelle piante sono cattive, ma alcune non sono del tutto tossiche. Le loro foglie possono avere usi medicinali.\n\nSaresti così gentile da portarmi delle Foglie Verdeggianti? Dovrai potare un po', ovviamente.", nil, nil, 0x62e6090d, 0x0f2ee49d, 0x53f147a3, nil, nil, "...mm" },
  [91758] = { "Segui quel coboldo!", "Parla con ⟦Tordrin Sternblade=Tordrin Lamasevera⟧ vicino alla stalla dietro l'Abbazia della Contea del Nord.", "Non hai ancora finito con quei coboldi. Kelsey ci ha appena fatto sapere che un coboldo è uscito dalla miniera con un grosso sacco di libri. Devi rintracciarlo, così potremo recuperare i libri per fratello Paxton.\n\nVa' a parlare con ⟦Tordrin Sternblade=Tordrin Lamasevera⟧. È il nuovo istruttore dei cacciatori, appena arrivato da ⟦Ironforge=Forgiardente⟧. Lo trovi dietro l'abbazia, vicino alla stalla. Può aiutarti a rintracciare questo coboldo ladro.", nil, "Posso aiutarti a scovare 'sta canaglia. Lascia che ti prepari qualcosa.", 0x5b4c7f86, 0xba85d0f1, 0xbabf3db2, nil, 0x0f74c33b, "...m." },
  [91770] = { "Morso di corteccia", "Applica l'impacco a Fraxinus.", "Con gli ingredienti che hai portato posso preparare una semplice medicina. Questo impiastro dovrebbe aiutare Fraxinus. È vecchio, sai, ed è stato gravemente ustionato durante le guerre. La sua corteccia fa male e gli dolgono gli arti. È il mio migliore amico e voglio solo che si senta meglio!\n\nPrendi questo impiastro e applicalo generosamente su tutti i punti in cui la sua corteccia è spaccata e la sua linfa cola.", nil, nil, 0x18325dd3, 0x17f18fe3, 0xf69f73af, nil, nil, "...mm" },
  [91772] = { "Ssst! Stiamo cacciando coboldi", "Segui le tracce dei coboldi e fai rapporto al maresciallo Dughan, a ⟦Goldshire=Borgodoro⟧, con le tue scoperte e il ⟦Kobold Tracking Kit=Kit da Tracciamento dei Coboldi⟧.", "Bene. Prendi questo kit per seguire le tracce dei coboldi. Ti permetterà di rintracciare il coboldo che preoccupa il maresciallo McBride.\n\nSegui le tracce e porta quel che trovi al maresciallo Dughan, a ⟦Goldshire=Borgodoro⟧.\n\nHo idea che 'ste canaglie stiano tramando qualcosa fuori dalla ⟦Northshire=Contea del Nord⟧. Quindi ti servirà l'aiuto di Dughan.", "Hai capito dove sono diretti i coboldi?", "Che cos'è questo, {name}? Seguire le tracce dei coboldi?\n\nBe', certo che sono diretti alla Miniera Antrocupo! Quel posto è infestato di coboldi.\n\nBuon lavoro, suppongo. Mi servirà qualcuno che si occupi di quel problema.", 0xccca4f37, 0x4c6f788d, 0x88b384bf, 0x76315b25, 0x94488fef, "....." },
  [91775] = { "Restituzione dei libri", "Trova 6 Lost Book e \"Fun with Elementals\" e riportali al maresciallo Dughan.", "Mentre indaghi nella ⟦Fargodeep Mine=Miniera Antrocupo⟧, vedi se riesci a trovare qualcuno dei libri di fratello Paxton da restituire. In particolare, Paxton è molto preoccupato per un libro intitolato \"Fun with Elementals\". Pensa che perfino un coboldo potrebbe usarlo per evocare un servitore elementale. Attenzione: le profondità della miniera sono piuttosto pericolose. Faresti bene a portare degli amici.\n\nPrendi questa borsa per proteggere i libri quando li trovi!", "Hai già trovato tutti i libri?", "Plaudo alla tua diligenza, {name}. ⟦Brother Paxton=Fratello Paxton⟧ mi ha mandato una lista di libri, e tu hai trovato quasi tutti quelli scomparsi. Gli altri devono essere stati portati nella ⟦Jasperlode Mine=Miniera Venarossa⟧.\n\nPuoi tenerti quella borsa per i libri!", 0xd01af3bc, 0x88f1a8d6, 0xf4a33e50, 0x546df3d0, 0xb1a94cf2, "....." },
  [91777] = { "Libri rari", "Recupera \"⟦Geomancy for Curious Young Wizards=Geomanzia per Giovani Maghi Curiosi⟧\" e \"⟦Arcane Explainer: Magical Stuff in Simple Words=Spiegazioni Arcane: Cose Magiche in Parole Semplici⟧\" e riportali a fratello Paxton, nell'Abbazia della Contea del Nord.", "Mancano all'appello solo due libri della lista di fratello Paxton: \"⟦Geomancy for Curious Young Wizards=Geomanzia per Giovani Maghi Curiosi⟧\" e \"⟦Arcane Explainer: Magical Stuff in Simple Words=Spiegazioni Arcane: Cose Magiche in Parole Semplici⟧\".\n\nI coboldi devono averli portati nella ⟦Jasperlode Mine=Miniera Venarossa⟧. Ti prego, rintraccia quei due libri e riportali a fratello Paxton.\n\nMa temo che sarà piuttosto pericoloso. Se il coboldo \"apprendista\" evocava un elementale, chissà cosa può fare il maestro. Al posto tuo porterei qualche amico.", "Hai già trovato tutti i miei libri scomparsi?", "Oh, {name}! Grazie mille per aver salvato la mia biblioteca. Mi hai reso un servizio straordinario. Prendi una di queste ottime armi, ti prego. Erano destinate alla milizia, ma tu puoi farne un uso migliore.", 0xa9c579cb, 0xa02ab9c4, 0xa51f628c, 0xf4232bfe, 0xb2abd943, "....." },
  [91794] = { "Le bandiere dei nostri avi", "Raccogli $N1 Bandiera dell'⟦Horde=Orda⟧ e $N2 Brandello d'Araldica dell'⟦Horde=Orda⟧ per Kal'tinzan nella Selva Antica.", "Siamo bloccati quassù da anni, sempre a combattere contro il Flagello, ma non perdiamo mai la speranza. Combattiamo per sopravvivere. Combattiamo per l'⟦Horde=Orda⟧. L'⟦Alliance=Alleanza⟧ condivide questa lotta, ma non dimentichiamo mai che abbiamo ancora una storia. Ancora sangue.\n\nLontano a est, a Dae'gun, ci sono bandiere dell'⟦Horde=Orda⟧ dalla guerra. I demoni portano pezzi e resti come trofei della battaglia, specie i più duri. Portami una bandiera e un po' di araldica così posso esporla e mostrare all'⟦Alliance=Alleanza⟧ che l'⟦Horde=Orda⟧ è ancora forte!", nil, nil, 0x533d301a, 0xf71a0616, 0x8fac4175, nil, nil, "...mm" },
  [91858] = { "Incidente diplomatico", "Raggiungi la ⟦The Sepulcher=Mausolea⟧, nella ⟦Silverpine Forest=Selva Pinargento⟧, e parla con Trevan Rol dei viaggiatori del Circolo della Terra scomparsi.", "Una sfortunatissima piega degli eventi a ⟦Silverpine=Pinargento⟧ ci offre un'occasione unica per dimostrare il nostro valore agli occhi dell'Orda.\n\nDue dignitari del Circolo della Terra sono scomparsi nella ⟦Silverpine Forest=Selva Pinargento⟧ mentre erano diretti al ⟦Tarren Mill=Mulino di Tarren⟧. Non sappiamo molto altro, ma si dice che la cosa stia diventando un vero incidente diplomatico. Se riusciamo a ritrovare gli scomparsi, potremmo ottenere la legittimità di cui abbiamo tanto bisogno.\n\nAbbiamo un uomo alla ⟦The Sepulcher=Mausolea⟧, Trevan Rol. Va' laggiù e parla con lui.", nil, "Ti ha mandato Danitha? Be', allora so già perché sei qui. Sei <capitato/capitata> in un maledetto pasticcio, {class}.", 0x860aa6df, 0x49857281, 0x51cda335, nil, 0xe436fee9, "...m." },
  [91859] = { "Una strana coppia", "Parla con il guardiamorte Baldren dei misteriosi viaggiatori del Circolo della Terra passati di recente per la ⟦The Sepulcher=Mausolea⟧.", "Vado dritto al punto: questi \"dignitari\" non sono diplomatici qualunque. Uno era un Tauren. Niente di strano per il Circolo della Terra, ma l'altro, e stenterai a crederci, era un elfo. Un *alto* elfo. Erano incappucciati, ma ho già visto dei quel'dorei e scommetterei il mio mignolo buono che è quello che ho visto.\n\nPerché un elfo accompagnava un Tauren attraverso il territorio dell'Orda? Be', ne so quanto te. Questo è tutto ciò che so, quindi ti suggerisco di parlare con il guardiamorte Baldren, vicino all'ingresso del paese.", nil, "Voi paladini non mi state granché simpatici, ma devo dire che il tuo tempismo è impeccabile. Meglio fortunati che bravi, no?", 0x81390067, 0x9840d880, 0x5b66726d, nil, 0x4666daba, "...m." },
  [91860] = { "Un triste destino", "Indaga sull'⟦Fenris Isle=Isola di Fenris⟧, a est, e scopri che fine ha fatto il gruppo di viaggiatori del Circolo della Terra.", "Ieri notte, durante la ronda, ho visto un gruppo di gnoll gettare un corpo molto grosso su una pira sulle rive dell'⟦Fenris Isle=Isola di Fenris⟧. Non ho visto né un elfo né cadaveri più piccoli, ma direi che per loro non promette niente di buono.\n\nSe sei <coraggioso/coraggiosa> o <stupido/stupida>, sei liber<o/a> di precipitarti sull'⟦Fenris Isle=Isola di Fenris⟧ per saperne di più, ma secondo me è un bel lavoro per trovare un elfo spocchioso che probabilmente è morto da un pezzo.\n\nLo so che voi paladini adorate giurare e abbracciare cause perse, ma questa non ne vale la pena. Fidati.", nil, "<Il cadavere davanti a te era senza dubbio di un Tauren, e si vede che è stato rosicchiato a lungo prima di essere gettato sulla pira. Però non vedi traccia dell'elfa che ti hanno descritto. Forse è ancora viva da qualche parte, più in profondità nella fortezza vicina?\n\nSarà pericoloso, ma c'è un solo modo per scoprirlo con certezza.>", 0x08dbafc9, 0x269e6b75, 0x06c5da17, nil, 0x0c72db2b, "...m." },
  [91861] = { "Dentro ⟦Fenris Keep=Forte Fenris⟧", "Indaga a ⟦Fenris Keep=Forte Fenris⟧, a nord, e cerca di ritrovare il membro scomparso del gruppo del Circolo della Terra.", "<Il fatto che tu abbia trovato un solo corpo è un segno di speranza. Forse l'alta elfa descritta da Trevan e Hadrec è ancora viva da qualche parte, più in profondità nella fortezza vicina?>", nil, "Sei uno dei Reietti, vero? Puoi aiutarmi a liberarmi?\n\nTemo di avere poco tempo. Ti prego, sbrigati!", 0x52a5ca6c, 0x05375492, 0xfcb8e7e8, nil, 0xc4755d7d, "...m." },
  [91862] = { nil, "Recupera la ⟦Fenris Isle Key=Chiave dell'Isola di Fenris⟧ dai Rot Hide Gnoll e usala per liberare Lumina Windsinger.", "Quel'dorei? No, non sono una \"quel'dorei\". Sono Lumina Windsinger e sono shen'dorei. Una dei Plasmatori di Venti dei Celesti.\n\nSono venuta in queste terre come ospite del Circolo della Terra. Il mio compagno Banon e io stavamo attraversando ⟦Silverpine=Pinargento⟧ per raggiungere gli ⟦Arathi Highlands=Altopiani d'Arathi⟧, dove volevamo studiare le convergenze elementali. Evidentemente non ci siamo riusciti.\n\nMa ora non abbiamo tempo per questo. Uccidi gli gnoll qui vicino. Recupera la chiave di questa gabbia e liberami. Ti racconterò il resto quando saremo al sicuro.", "Gli gnoll sono le seconde creature peggiori che abbia incontrato finora su Azeroth.", "Grazie, {class}. Purtroppo non siamo ancora fuori pericolo.", 0x8615ca23, 0x9d3e70b4, 0x1c33efa2, 0xd342e852, 0x59d83bf0, "e...." },
  [91877] = { "Il cacciatore del cacciatore di demoni", "Trova Maerion Thaelemaches da qualche parte sul ⟦Mount Hyjal=Monte Hyjal⟧.", "Non sono rimasti molti cacciatori di demoni su Azeroth ormai, ma alcuni di noi continuano a dare la caccia alle minacce più pericolose o nascoste.\n\nUn mio collega, Maerion Thaelemaches, si è diretto a Hyjal per indagare sulle voci di demoni in quella zona. Anche se nella pericolosa ⟦Darkwhisper Gorge=Gola di Mormoscuro⟧ i demoni sono molti, si sospetta che i demoni che hanno assaltato la montagna durante l'ultima guerra possano non essere stati del tutto sconfitti.\n\nLa cosa merita un'indagine.", nil, nil, 0x1a96d6d2, 0xe1469e67, 0xddf8270c, nil, nil, "...mm" },
  [91881] = { "L'avamposto occidentale", "Incontra Sefira Fulgeterno all'avamposto.", "Con gli stregoni sotto controllo, direi che quest'area è ben sotto le mie ali.\n\n<Il corvo annuisce con saggezza, compiaciuto.>\n\nAnche se il nostro lavoro qui è finito, ci sono altre zone che potrebbero avere bisogno del tuo aiuto e, come mio pupillo, vorrei che andassi a vedere di cosa si tratta.\n\nSegui il sentiero a nordovest lungo la strada fino al vecchio avamposto delle sterne. Un vecchio amico ti aspetta!", nil, nil, 0x68ca4f6b, 0x6328b885, 0xc7933518, nil, nil, "...mm" },
  [91882] = { "La Grande ⟦Alliance=Alleanza⟧", "Cerca sul ⟦Mount Hyjal=Monte Hyjal⟧ i resti della Grande ⟦Alliance=Alleanza⟧.", "Anni fa, l'⟦Horde=Orda⟧ e l'⟦Alliance=Alleanza⟧ misero da parte le loro divergenze per combattere una minaccia più grande: la Legione. Sul ⟦Mount Hyjal=Monte Hyjal⟧, le forze della Grande ⟦Alliance=Alleanza⟧ fermarono Archimonde e i suoi servitori.\n\nLa ritirata dalla montagna fu però pericolosa e alcuni coraggiosi combattenti furono lasciati indietro.\n\nOra che la via per la grande montagna è di nuovo aperta, forse alcuni di questi eroi sono ancora vivi nelle terre selvagge? Va' sul ⟦Mount Hyjal=Monte Hyjal⟧ e affronta i suoi pericoli. Scopri che ne è stato delle nostre forze.", nil, nil, 0xc672f821, 0x330740bf, 0x531abf0d, nil, nil, "...mm" },
  [91883] = { "La lancia del Signore del Cielo", "Uccidi Zarrat Alaverme e restituisci la Lancia di Omnuron.", "Mentre combattevo le arpie Alaverme, un'arpia di nome Zarrat che pattuglia questa zona mi ha teso un'imboscata brutale. Mi ha strappato la lancia e l'ha portata via prima che potessi recuperarla. Con quale scopo volesse possederla, non saprei dirlo.\n\nQuella lancia è nella mia famiglia da generazioni ed è di grande importanza per me. Se individui Zarrat tra le arpie, uccidila e riportami la lancia. È furtiva e non sarà facile trovarla, ma ti sarei grato di riavere la mia lancia.", nil, nil, 0xbe01f727, 0x16f2fa57, 0x9047ad29, nil, nil, "...mm" },
  [91899] = { "Una ⟦Sealed Crate=Cassa Sigillata⟧", nil, nil, "Un'altra consegna! Fantastico. Mettila lì vicino alla pila e parliamo del tuo compenso.", "Grazie per il tuo impegno, {name}. Ultimamente c'è stata un'ondata di banditi e ladri che intercettano le rotte commerciali. Se trovi altre casse in giro, portale qui e al resto penseremo noi.\n\nEcco il tuo compenso.", 0xfc2b137e, nil, nil, 0x5e066350, 0x8ac6a9d3, ".mm.." },
  [91900] = { "Una ⟦Sealed Crate=Cassa Sigillata⟧", nil, nil, "Un'altra consegna! Fantastico. Mettila lì vicino alla pila e parliamo del tuo compenso.", "Grazie per il tuo impegno, {name}. Ultimamente c'è stata un'ondata di banditi e ladri che intercettano le rotte commerciali. Se trovi altre casse in giro, portale qui e al resto penseremo noi.\n\nEcco il tuo compenso.", 0xfc2b137e, nil, nil, 0x5e066350, 0x8ac6a9d3, ".mm.." },
  [91901] = { "Una ⟦Sealed Crate=Cassa Sigillata⟧", nil, nil, "Un'altra consegna! Fantastico. Mettila vicino alla pila e parliamo del tuo compenso.", "Grazie per il tuo duro lavoro, {name}. Ultimamente c'è stata un'impennata di banditi e ladri che intercettano le rotte commerciali. Se trovi altre casse in giro, portale qui e ce ne occuperemo noi.\n\nEcco il tuo compenso.", 0xfc2b137e, nil, nil, 0x5e066350, 0x8ac6a9d3, ".mm.." },
  [91902] = { "Una ⟦Sealed Crate=Cassa Sigillata⟧", nil, nil, nil, nil, 0xfc2b137e, nil, nil, nil, nil, ".mmmm" },
