  [91905] = { "Una ⟦Sealed Crate=Cassa Sigillata⟧", nil, nil, "Un'altra consegna! Fantastico. Mettila vicino alla pila e parliamo del tuo compenso.", "Grazie per il tuo duro lavoro, {name}. Ultimamente c'è stata un'impennata di banditi e ladri che intercettano le rotte commerciali. Se trovi altre casse in giro, portale qui e ce ne occuperemo noi.\n\nEcco il tuo compenso.", 0xfc2b137e, nil, nil, 0x5e066350, 0x8ac6a9d3, ".mm.." },
